from datetime import date, datetime

from sqlalchemy import (
    Date,
    DateTime,
    ForeignKey,
    Index,
    Integer,
    JSON,
    String,
    UniqueConstraint,
    func,
)
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.database import Base


class MesocyclePlan(Base):
    """Four-week mesocycle plan generated by the periodization engine.

    Each row represents a single 4-week block for one athlete anchored at
    ``plan_start_date`` (always a Monday).  The generator is idempotent on
    ``(user_id, plan_start_date)`` — re-running for the same anchor returns the
    existing row unchanged.

    Column notes
    ────────────
    ``phase``               Friel phase detected at generation time (base1/build2/…).
    ``block_index``         0-indexed week within the meso (0..3); 0-2 are build,
                            3 is the Issurin recovery week.
    ``weekly_tss_targets``  JSON list of 4 ints — TSS budgets per week; encodes the
                            Issurin 3:1 ramp.  E.g. [380, 420, 460, 280].
    ``seiler_distribution`` Per-plan Seiler TID snapshot: {"z1_pct": 0.80,
                            "z2_pct": 0.05, "z3_pct": 0.15}.
    ``target_event_date``   Copied from AthleteProfile at generation time for audit.
    ``evidence``            Generation-time snapshot for debugging: CTL, FTP,
                            days_to_goal, plan_start_date.
    """

    __tablename__ = "mesocycle_plans"

    __table_args__ = (
        UniqueConstraint("user_id", "plan_start_date", name="uq_mesocycle_user_start"),
        Index("ix_mesocycle_user_end", "user_id", "plan_end_date"),
        {"comment": "Four-week periodization block plans with Issurin 3:1 structure"},
    )

    id: Mapped[int] = mapped_column(Integer, primary_key=True, index=True)
    user_id: Mapped[int] = mapped_column(
        Integer,
        ForeignKey("users.id", ondelete="CASCADE"),
        nullable=False,
        index=True,
    )
    plan_start_date: Mapped[date] = mapped_column(Date, nullable=False, index=True)
    plan_end_date: Mapped[date] = mapped_column(Date, nullable=False)

    # Friel phase at generation time
    phase: Mapped[str] = mapped_column(String(20), nullable=False)

    # 0-indexed week position within the current meso (0..3)
    block_index: Mapped[int] = mapped_column(Integer, nullable=False, default=0)

    # Issurin 3:1 weekly TSS budgets — list of 4 ints
    weekly_tss_targets: Mapped[list] = mapped_column(JSON, nullable=False)

    # Seiler distribution snapshot at generation time
    seiler_distribution: Mapped[dict] = mapped_column(JSON, nullable=False)

    # Audit columns — copied from AthleteProfile at generation time
    target_event_date: Mapped[date | None] = mapped_column(Date, nullable=True)
    target_event_type: Mapped[str | None] = mapped_column(String(20), nullable=True)

    # Debug snapshot: {"ctl": float, "ftp_watts": int, "days_to_goal": int|null}
    evidence: Mapped[dict | None] = mapped_column(JSON, nullable=True)

    # Timestamps
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        server_default=func.now(),
        nullable=False,
    )
    updated_at: Mapped[datetime | None] = mapped_column(
        DateTime(timezone=True),
        onupdate=func.now(),
        nullable=True,
    )

    # Relationships
    user: Mapped["User"] = relationship("User")  # noqa: F821
